<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ArrowPathIcon, ChevronRightIcon, InboxArrowDownIcon, MagnifyingGlassIcon, PaperAirplaneIcon, PlusIcon, PrinterIcon } from '@heroicons/vue/24/outline'
import { useAccountStore } from '@/domains/accounts/stores/accountStore'
import FaxBoxFormPanel from '../components/FaxBoxFormPanel.vue'; import FaxDetailPanel from '../components/FaxDetailPanel.vue'
import { useFaxStore } from '../stores/faxStore'; import type { FaxBoxInput } from '../types/fax'
const accounts = useAccountStore(); const faxes = useFaxStore(); const boxPanel = ref(false); const messagePanel = ref(false)
const canManage = computed(() => accounts.selected?.permissions.can_manage_call_routing ?? false)
watch(() => accounts.selectedId, (id) => { boxPanel.value = false; messagePanel.value = false; faxes.reset(); if (id) void faxes.load(id) }, { immediate: true })
async function openBox(id?: string): Promise<void> { if (!accounts.selectedId) return; await faxes.prepareBox(accounts.selectedId, id); boxPanel.value = true }
async function openMessage(id: string): Promise<void> { if (!accounts.selectedId) return; await faxes.prepareMessage(accounts.selectedId, id); messagePanel.value = true }
async function saveBox(input: FaxBoxInput): Promise<void> { if (accounts.selectedId && await faxes.saveBox(accounts.selectedId, input)) boxPanel.value = false }
async function removeBox(): Promise<void> { if (accounts.selectedId && await faxes.removeBox(accounts.selectedId)) boxPanel.value = false }
</script>
<template><section class="border-b border-slate-200/80 bg-white px-4 py-5 sm:px-6 lg:px-8"><div class="mx-auto flex max-w-[1500px] items-center gap-4"><div><p class="mb-1 text-[11px] text-slate-400">GridPBX / Fax</p><h1 class="text-xl font-semibold text-slate-800">Fax boxes & history</h1><p class="mt-1 text-xs text-slate-500">Configure inbound fax boxes and securely access projected message documents.</p></div><div class="ml-auto flex gap-2"><button v-if="canManage" :disabled="faxes.synchronizing" class="inline-flex h-9 items-center gap-2 rounded-md border border-slate-200 bg-white px-4 text-xs font-semibold text-slate-600 disabled:opacity-40" @click="accounts.selectedId && faxes.synchronize(accounts.selectedId)"><ArrowPathIcon class="size-4" :class="faxes.synchronizing && 'animate-spin'" />Sync</button><button v-if="canManage" class="inline-flex h-9 items-center gap-2 rounded-md bg-brand-500 px-4 text-xs font-semibold text-white" @click="openBox()"><PlusIcon class="size-4" />New fax box</button></div></div></section>
<div class="mx-auto grid max-w-[1500px] gap-6 p-4 sm:p-6 lg:p-8"><div v-if="faxes.error" class="rounded-md border border-red-100 bg-red-50 p-4 text-xs text-danger">{{ faxes.error }}</div><section><div class="mb-3 flex items-center gap-2"><PrinterIcon class="size-5 text-brand-500" /><h2 class="text-sm font-semibold text-slate-700">Fax boxes</h2></div><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><button v-for="box in faxes.boxes" :key="box.id" type="button" class="card-surface p-5 text-left transition hover:-translate-y-0.5 hover:shadow-md" @click="openBox(box.id)"><div class="flex items-start gap-3"><span class="grid size-9 place-items-center rounded-md bg-brand-50 text-brand-600"><PrinterIcon class="size-4" /></span><div class="min-w-0 flex-1"><p class="truncate text-sm font-semibold text-slate-700">{{ box.name }}</p><p class="mt-1 truncate text-[10px] text-slate-400">{{ box.smtp_email_address || 'No SMTP address' }}</p></div><ChevronRightIcon class="size-4 text-slate-400" /></div><div class="mt-4 flex items-center justify-between border-t border-slate-100 pt-3 text-[10px] text-slate-500"><span>{{ box.owner?.label || 'No owner' }}</span><span>{{ box.fax_count ?? 0 }} faxes</span></div></button><p v-if="!faxes.loading && !faxes.boxes.length" class="card-surface col-span-full p-8 text-center text-xs text-slate-400">No fax boxes are projected.</p></div></section>
<section><div class="mb-3 flex items-center gap-2"><InboxArrowDownIcon class="size-5 text-brand-500" /><h2 class="text-sm font-semibold text-slate-700">Fax history</h2><span class="text-[10px] text-slate-400">{{ faxes.total }} projected</span></div><form class="mb-4 flex gap-3" @submit.prevent="accounts.selectedId && faxes.load(accounts.selectedId)"><label class="relative min-w-0 flex-1"><MagnifyingGlassIcon class="absolute top-1/2 left-3 size-4 -translate-y-1/2 text-slate-400" /><input v-model="faxes.search" type="search" placeholder="Search sender, recipient, or subject…" class="h-10 w-full rounded-md border border-slate-200 bg-white pr-3 pl-9 text-xs" /></label><FormSelect v-model="faxes.folder" class="h-10 rounded-md border border-slate-200 bg-white px-3 text-xs"><option value="">Inbox & outbox</option><option value="inbox">Inbox</option><option value="outbox">Outbox</option></FormSelect><FormSelect v-model="faxes.faxBoxId" class="h-10 rounded-md border border-slate-200 bg-white px-3 text-xs"><option value="">All fax boxes</option><option v-for="box in faxes.boxes" :key="box.id" :value="box.id">{{ box.name }}</option></FormSelect><button class="h-10 rounded-md border border-slate-200 bg-white px-5 text-xs font-semibold text-slate-600">Search</button></form><div class="card-surface overflow-hidden"><table class="w-full text-left"><thead class="border-b border-slate-100 bg-slate-50/70 text-[10px] font-bold tracking-wider text-slate-400 uppercase"><tr><th class="px-5 py-3.5">Direction</th><th class="px-5 py-3.5">From / To</th><th class="px-5 py-3.5">Fax box</th><th class="px-5 py-3.5">Pages</th><th class="px-5 py-3.5">Status</th><th class="w-12"></th></tr></thead><tbody class="divide-y divide-slate-100 text-xs"><tr v-if="faxes.loading"><td colspan="6" class="px-5 py-14 text-center text-slate-400">Loading faxes…</td></tr><tr v-else-if="!faxes.messages.length"><td colspan="6" class="px-5 py-14 text-center text-slate-400">No faxes match the current filters.</td></tr><tr v-for="fax in faxes.messages" v-else :key="fax.id" class="cursor-pointer hover:bg-slate-50" @click="openMessage(fax.id)"><td class="px-5 py-4"><span class="inline-flex items-center gap-1.5 font-semibold" :class="fax.folder === 'inbox' ? 'text-emerald-600' : 'text-brand-600'"><InboxArrowDownIcon v-if="fax.folder === 'inbox'" class="size-4" /><PaperAirplaneIcon v-else class="size-4" />{{ fax.folder }}</span></td><td class="px-5 py-4"><p class="font-semibold text-slate-700">{{ fax.folder === 'inbox' ? fax.from.number : fax.to.number }}</p><p class="text-[10px] text-slate-400">{{ fax.created_at ? new Date(fax.created_at).toLocaleString() : 'Unknown time' }}</p></td><td class="px-5 py-4 text-slate-500">{{ fax.fax_box?.name || 'Unassigned' }}</td><td class="px-5 py-4 text-slate-500">{{ fax.pages }}</td><td class="px-5 py-4"><span class="rounded-full px-2 py-1 text-[10px] font-semibold" :class="fax.successful === false ? 'bg-red-50 text-red-700' : fax.successful === true ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'">{{ fax.status || 'Unknown' }}</span></td><td><ChevronRightIcon class="size-4 text-slate-400" /></td></tr></tbody></table></div></section></div>
<FaxBoxFormPanel v-if="boxPanel" :record="faxes.boxDetail" :options="faxes.options" :saving="faxes.saving" :error="faxes.mutationError" :field-errors="faxes.fieldErrors" :can-manage="canManage" @close="boxPanel = false" @save="saveBox" @remove="removeBox" /><FaxDetailPanel v-if="messagePanel && faxes.messageDetail" :record="faxes.messageDetail" :downloading="faxes.downloading" :error="faxes.mutationError" @close="messagePanel = false" @download="accounts.selectedId && faxes.download(accounts.selectedId)" /></template>
